def VQE_2(parameters=None):
    """Prepare a two-qubit variational state and return 1000 samples."""
    parameters = np.zeros(8) if parameters is None else np.asarray(parameters)
    if parameters.shape != (8,) or not np.isrealobj(parameters):
        raise ValueError("parameters must contain exactly 8 real values.")

    dev = qml.device("default.qubit", wires=2, shots=1000)

    @qml.qnode(dev)
    def circuit(params):
        for offset in (0, 4):
            qml.RZ(params[offset], wires=0)
            qml.RZ(params[offset + 1], wires=0)
            qml.RY(params[offset + 2], wires=0)
            qml.RZ(params[offset + 3], wires=1)
        return qml.sample()

    return circuit(parameters)

from qiskit import QuantumRegister, ClassicalRegister, QuantumCircuit

def qaoa_maxcut_ansatz(G, beta, gamma) -> QuantumCircuit:
    """Build and measure a five-layer QAOA MaxCut ansatz."""
    if len(beta) != 5 or len(gamma) != 5:
        raise ValueError("beta and gamma must each contain 5 parameters.")

    nodes = list(G.nodes())
    node_index = {node: i for i, node in enumerate(nodes)}
    n = len(nodes)

    qr = QuantumRegister(n, "q")
    cr = ClassicalRegister(n, "c")
    circuit = QuantumCircuit(qr, cr)

    circuit.h(qr)

    for layer in range(5):
        for u, v in G.edges():
            circuit.rzz(-gamma[layer], qr[node_index[u]], qr[node_index[v]])

        for qubit in qr:
            circuit.rx(2 * beta[layer], qubit)

    circuit.measure(qr, cr)
    return circuit
